template<>struct Wire<RG_RULE> {static Json Encode(const RG_RULE& v){Json j=Json::object();j["Id"]=EncodeWire(v.Id);j["Action"]=EncodeWire(v.Action);j["Chars"]=EncodeWire(v.Chars);j["Reserved"]=EncodeWire(v.Reserved);j["Path"]=EncodeWire(v.Path);return j;}static void Decode(const Json& j,RG_RULE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Id")DecodeWire(it.value(),v.Id);else if(it.key()=="Action")DecodeWire(it.value(),v.Action);else if(it.key()=="Chars")DecodeWire(it.value(),v.Chars);else if(it.key()=="Reserved")DecodeWire(it.value(),v.Reserved);else if(it.key()=="Path")DecodeWire(it.value(),v.Path);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
